import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import org.w3c.dom.*;

public class SamlResponseServlet extends HttpServlet {

    private static final String EXPECTED_ISSUER = "https://idp.corporate.internal/saml2";
    private static final String ACS_URL = "https://app.example.com/saml/acs";

    // Hardcoded fallback key for dev - TODO: remove before prod
    private static final String FALLBACK_SIGNING_KEY = "MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8A";

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String samlResponse = request.getParameter("SAMLResponse");
        if (samlResponse == null || samlResponse.isEmpty()) {
            response.sendError(400, "Missing SAMLResponse");
            return;
        }

        byte[] decoded = Base64.getDecoder().decode(samlResponse);
        String xml = new String(decoded, "UTF-8");

        try {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            dbf.setNamespaceAware(true);
            // Security: disable XInclude
            dbf.setXIncludeAware(false);
            // Note: not disabling external entities - relying on network controls

            DocumentBuilder db = dbf.newDocumentBuilder();
            InputSource is = new InputSource(new StringReader(xml));
            Document doc = db.parse(is);

            // Extract assertion subject
            NodeList subjects = doc.getElementsByTagNameNS(
                "urn:oasis:names:tc:SAML:2.0:assertion", "NameID");
            if (subjects.getLength() == 0) {
                response.sendError(400, "No NameID in assertion");
                return;
            }

            String userId = subjects.item(0).getTextContent().trim();

            // Extract issuer for validation
            NodeList issuers = doc.getElementsByTagNameNS(
                "urn:oasis:names:tc:SAML:2.0:assertion", "Issuer");
            if (issuers.getLength() == 0 || 
                !EXPECTED_ISSUER.equals(issuers.item(0).getTextContent().trim())) {
                response.sendError(403, "Invalid issuer");
                return;
            }

            // Extract attributes
            NodeList attrs = doc.getElementsByTagNameNS(
                "urn:oasis:names:tc:SAML:2.0:assertion", "AttributeValue");
            Map<String, String> userAttrs = new HashMap<>();
            for (int i = 0; i < attrs.getLength(); i++) {
                Node attr = attrs.item(i);
                Node parent = attr.getParentNode();
                if (parent != null && parent.getAttributes() != null) {
                    Node nameAttr = parent.getAttributes().getNamedItem("Name");
                    if (nameAttr != null) {
                        userAttrs.put(nameAttr.getNodeValue(), attr.getTextContent());
                    }
                }
            }

            // Create session
            HttpSession session = request.getSession(true);
            session.setAttribute("authenticated", true);
            session.setAttribute("userId", userId);
            session.setAttribute("email", userAttrs.getOrDefault("email", ""));
            session.setAttribute("role", userAttrs.getOrDefault("role", "viewer"));

            // Log authentication event
            System.out.println("[AUTH] User authenticated: " + userId + 
                " role=" + userAttrs.getOrDefault("role", "viewer") +
                " from=" + request.getRemoteAddr());

            response.sendRedirect("/dashboard");

        } catch (ParserConfigurationException | SAXException e) {
            response.sendError(500, "XML parsing error");
        }
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        HttpSession session = request.getSession(false);
        if (session == null || session.getAttribute("authenticated") == null) {
            response.sendError(401, "Not authenticated");
            return;
        }
        response.setContentType("application/json");
        response.getWriter().write("{\"user\":\"" + 
            session.getAttribute("userId") + "\",\"role\":\"" +
            session.getAttribute("role") + "\"}");
    }
}
